<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { CircleCheck, CircleClose, DocumentChecked, Hide, Refresh, Search, View } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { api, hasPermission } from '../api'
import '../admin.css'

const auditTabs = [{ name: 'TOPIC', label: '专题' }, { name: 'ARTICLE', label: '资讯' }, { name: 'SUPPLIER', label: '供应商资质' }, { name: 'SOLUTION', label: '解决方案' }]
const activeTab = ref('TOPIC'); const loading = ref(false); const logLoading = ref(false); const error = ref('')
const queue = ref({ records: [], total: 0, current: 1, size: 20 }); const logs = ref({ records: [], total: 0, current: 1, size: 20 })
const pendingCounts = ref({ TOPIC: 0, ARTICLE: 0, SUPPLIER: 0, SOLUTION: 0 }); const filter = reactive({ status: 'PENDING', keyword: '', dates: [] }); const logFilter = reactive({ bizType: '', keyword: '' })
const page = ref(1); const logPage = ref(1); const dialogVisible = ref(false); const selected = ref(null); const histories = ref([]); const reviewing = ref(false); const decision = ref('APPROVED'); const opinion = ref('')
const canAudit = computed(() => hasPermission('platform:audit')); const isLog = computed(() => activeTab.value === 'LOG')
const statusLabels = { DRAFT: '草稿', PENDING: '待审核', APPROVED: '已通过', REJECTED: '已驳回', OFFLINE: '已下线', DELETED: '已删除' }; const actionLabels = { APPROVED: '通过', REJECTED: '驳回', OFFLINE: '下线', DELETED: '删除' }; const statusTypes = { APPROVED: 'success', PENDING: 'warning', REJECTED: 'danger', OFFLINE: 'info', DRAFT: 'info', DELETED: 'danger' }
function statusLabel(status) { return statusLabels[status] || status || '未设置' }; function statusType(status) { return statusTypes[status] || 'info' }; function formatDate(value) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '未记录' }
function statusOptions() { return [{ label: '全部状态', value: '' }, ...Object.entries(statusLabels).map(([value, label]) => ({ label, value }))] }; function queryString(params) { return new URLSearchParams(Object.entries(params).filter(([, value]) => value !== '' && value != null)).toString() }
async function responseMessage(response, fallback) { try { return (await response.json()).message || fallback } catch { return fallback } }
async function loadQueue() { if (!canAudit.value) { error.value = '当前账号没有审核运营权限，请使用平台管理员账号登录。'; return }; loading.value = true; error.value = ''; try { const params = { bizType: activeTab.value, status: filter.status, keyword: filter.keyword, startDate: filter.dates?.[0], endDate: filter.dates?.[1], page: page.value, size: 20 }; const response = await api(`/api/admin/audits/queue?${queryString(params)}`); if (!response.ok) throw new Error(await responseMessage(response, '审核队列加载失败')); queue.value = await response.json() } catch (e) { error.value = e.message } finally { loading.value = false } }
async function loadLogs() { if (!canAudit.value) return; logLoading.value = true; error.value = ''; try { const response = await api(`/api/admin/audits/logs?${queryString({ ...logFilter, page: logPage.value, size: 20 })}`); if (!response.ok) throw new Error(await responseMessage(response, '审核日志加载失败')); logs.value = await response.json() } catch (e) { error.value = e.message } finally { logLoading.value = false } }
async function loadPendingCounts() { if (!canAudit.value) return; const results = await Promise.all(auditTabs.map(async item => { const response = await api(`/api/admin/audits/queue?bizType=${item.name}&status=PENDING&page=1&size=1`); return [item.name, response.ok ? (await response.json()).total : 0] })); pendingCounts.value = Object.fromEntries(results) }
async function switchTab(name) { activeTab.value = name; if (name === 'LOG') await loadLogs(); else { page.value = 1; await loadQueue() } }
function search() { page.value = 1; loadQueue() }; function resetFilter() { Object.assign(filter, { status: 'PENDING', keyword: '', dates: [] }); search() }; function actionAvailable(status, value) { if (value === 'OFFLINE') return status === 'APPROVED'; if (value === 'APPROVED') return ['DRAFT', 'PENDING', 'REJECTED', 'OFFLINE'].includes(status); return ['DRAFT', 'PENDING', 'REJECTED'].includes(status) }
const decisionOptions = computed(() => selected.value ? ['APPROVED', 'REJECTED', 'OFFLINE'].filter(value => actionAvailable(selected.value.item.status, value)).map(value => ({ label: actionLabels[value], value })) : [])
async function openDetail(row, value) { error.value = ''; selected.value = null; histories.value = []; decision.value = value || ''; opinion.value = ''; try { const [detailResponse, historyResponse] = await Promise.all([api(`/api/admin/audits/${row.bizType}/${row.id}`), api(`/api/admin/audits/${row.bizType}/${row.id}/history`)]); if (!detailResponse.ok) throw new Error(await responseMessage(detailResponse, '审核详情加载失败')); selected.value = await detailResponse.json(); histories.value = historyResponse.ok ? await historyResponse.json() : []; dialogVisible.value = true } catch (e) { error.value = e.message } }
async function submitAudit() { if (!selected.value) return; if (decision.value === 'REJECTED' && !opinion.value.trim()) { ElMessage.error('请填写驳回原因，便于提交人修改。'); return }; reviewing.value = true; error.value = ''; try { const item = selected.value.item; const response = await api(`/api/admin/audits/${item.bizType}/${item.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: decision.value, opinion: opinion.value }) }); if (!response.ok) throw new Error(await responseMessage(response, '审核操作失败')); dialogVisible.value = false; ElMessage.success(`已${actionLabels[decision.value]}`); await Promise.all([loadQueue(), loadPendingCounts()]) } catch (e) { error.value = e.message } finally { reviewing.value = false } }
function changeQueuePage(value) { page.value = value; loadQueue() }; function changeLogPage(value) { logPage.value = value; loadLogs() }; function refresh() { isLog.value ? loadLogs() : Promise.all([loadQueue(), loadPendingCounts()]) }
onMounted(async () => { await Promise.all([loadQueue(), loadPendingCounts()]) })
</script>

<template>
  <section class="audit-admin" v-loading="loading && !isLog">
    <header class="audit-header"><div><h1>审核运营后台</h1><p>审核专题、资讯、企业资质和解决方案，并保留每次操作的可追溯记录。</p></div><div class="audit-header-actions"><RouterLink class="el-button" to="/admin/content">内容管理</RouterLink><RouterLink class="el-button" to="/admin/supplier-memberships">会员与投放</RouterLink><RouterLink class="el-button" to="/admin/ai-reports">汇报授权</RouterLink><RouterLink class="el-button" to="/admin/homepage">首页运营</RouterLink><RouterLink class="el-button" to="/admin/taxonomies">分类管理</RouterLink><RouterLink class="el-button" to="/operations/leads">线索运营</RouterLink><RouterLink class="el-button" to="/">返回门户</RouterLink><el-button :icon="Refresh" @click="refresh">刷新</el-button></div></header>
    <el-alert v-if="error" class="audit-alert" :title="error" type="error" show-icon closable @close="error = ''" />
    <div v-if="canAudit" class="pending-strip" aria-label="待审核数量"><button v-for="item in auditTabs" :key="item.name" :class="{ active: activeTab === item.name && filter.status === 'PENDING' }" @click="activeTab = item.name; filter.status = 'PENDING'; page = 1; loadQueue()"><span>{{ item.label }}待审</span><strong>{{ pendingCounts[item.name] || 0 }}</strong></button></div>
    <el-tabs v-if="canAudit" :model-value="activeTab" class="audit-tabs" @tab-change="switchTab"><el-tab-pane v-for="item in auditTabs" :key="item.name" :label="item.label" :name="item.name" /><el-tab-pane label="审核日志" name="LOG" /></el-tabs>
    <template v-if="canAudit && !isLog">
      <form class="audit-filter" @submit.prevent="search"><el-select v-model="filter.status" aria-label="审核状态" style="width:132px"><el-option v-for="item in statusOptions()" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-input v-model="filter.keyword" :prefix-icon="Search" placeholder="按标题、企业名称检索" clearable /><el-date-picker v-model="filter.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="提交开始日" end-placeholder="提交结束日" range-separator="至" /><el-button type="primary" native-type="submit">查询</el-button><el-button @click="resetFilter">重置</el-button></form>
      <section class="audit-table-wrap"><div class="table-caption"><span>{{ auditTabs.find(item => item.name === activeTab)?.label }}审核队列</span><small>共 {{ queue.total }} 条</small></div><el-table :data="queue.records" empty-text="当前筛选条件下没有记录"><el-table-column label="内容" min-width="260"><template #default="{ row }"><strong class="record-title">{{ row.title }}</strong><span class="record-detail">{{ row.detail || '资料待补充' }}</span></template></el-table-column><el-table-column prop="submitter" label="提交主体" min-width="145" show-overflow-tooltip /><el-table-column label="当前状态" width="112"><template #default="{ row }"><el-tag :type="statusType(row.status)" effect="plain">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="提交时间" width="174"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="244" fixed="right"><template #default="{ row }"><el-button :icon="View" link type="primary" @click="openDetail(row)">详情</el-button><el-button v-if="actionAvailable(row.status, 'APPROVED')" :icon="CircleCheck" link type="success" @click="openDetail(row, 'APPROVED')">通过</el-button><el-button v-if="actionAvailable(row.status, 'REJECTED')" :icon="CircleClose" link type="danger" @click="openDetail(row, 'REJECTED')">驳回</el-button><el-button v-if="actionAvailable(row.status, 'OFFLINE')" :icon="Hide" link type="info" @click="openDetail(row, 'OFFLINE')">下线</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="queue.total" layout="total, prev, pager, next" @current-change="changeQueuePage" /></div></section>
    </template>
    <template v-else-if="canAudit">
      <form class="audit-filter log-filter" @submit.prevent="logPage = 1; loadLogs()"><el-select v-model="logFilter.bizType" aria-label="业务类型" style="width:160px"><el-option label="全部业务类型" value="" /><el-option v-for="item in auditTabs" :key="item.name" :label="item.label" :value="item.name" /></el-select><el-input v-model="logFilter.keyword" :prefix-icon="Search" placeholder="审核人或审核意见" clearable /><el-button type="primary" native-type="submit">查询日志</el-button></form>
      <section class="audit-table-wrap" v-loading="logLoading"><div class="table-caption"><span>审核操作日志</span><small>共 {{ logs.total }} 条</small></div><el-table :data="logs.records" empty-text="尚无审核操作记录"><el-table-column label="业务类型" width="130"><template #default="{ row }">{{ auditTabs.find(item => item.name === row.bizType)?.label || row.bizType }}</template></el-table-column><el-table-column prop="bizId" label="记录 ID" width="105" /><el-table-column label="操作" width="105"><template #default="{ row }"><el-tag :type="statusType(row.action)" effect="plain">{{ actionLabels[row.action] || row.action }}</el-tag></template></el-table-column><el-table-column label="状态变化" min-width="150"><template #default="{ row }">{{ statusLabel(row.beforeStatus) }} → {{ statusLabel(row.afterStatus) }}</template></el-table-column><el-table-column prop="opinion" label="审核意见" min-width="260" show-overflow-tooltip /><el-table-column prop="operatorName" label="审核人" width="125" /><el-table-column label="操作时间" width="174"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="logPage" :page-size="20" :total="logs.total" layout="total, prev, pager, next" @current-change="changeLogPage" /></div></section>
    </template>
    <section v-else class="audit-denied"><el-icon><DocumentChecked /></el-icon><h2>无审核运营权限</h2><p>请使用具备平台审核权限的运营管理员账号登录后再访问此页面。</p><RouterLink class="el-button el-button--primary" to="/login">前往登录</RouterLink></section>
    <el-dialog v-model="dialogVisible" :title="decision === 'APPROVED' ? '审核并通过' : decision === 'REJECTED' ? '审核并驳回' : decision === 'OFFLINE' ? '下线内容' : '审核详情'" width="min(760px, 94vw)" class="audit-dialog"><template v-if="selected"><div class="audit-detail-heading"><div><h2>{{ selected.item.title }}</h2><span>{{ selected.item.submitter }} · {{ selected.item.detail || '资料待补充' }}</span></div><el-tag :type="statusType(selected.item.status)" effect="plain">{{ statusLabel(selected.item.status) }}</el-tag></div><dl class="audit-metadata"><div><dt>提交时间</dt><dd>{{ formatDate(selected.item.createdAt) }}</dd></div><div v-if="selected.sourceUrl"><dt>来源链接</dt><dd><a :href="selected.sourceUrl" target="_blank" rel="noreferrer">查看来源</a></dd></div></dl><div v-if="selected.summary" class="audit-copy"><h3>摘要</h3><p>{{ selected.summary }}</p></div><div v-if="selected.content" class="audit-copy"><h3>正文或方案说明</h3><p>{{ selected.content }}</p></div><section class="history"><h3>审核历史</h3><el-timeline v-if="histories.length"><el-timeline-item v-for="entry in histories" :key="entry.id" :timestamp="formatDate(entry.createdAt)" :type="statusType(entry.action)"><strong>{{ entry.operatorName }}{{ actionLabels[entry.action] || entry.action }}</strong><span v-if="entry.opinion">：{{ entry.opinion }}</span></el-timeline-item></el-timeline><el-empty v-else :image-size="48" description="尚无审核历史" /></section><el-form v-if="decision" label-position="top" class="audit-decision"><el-form-item label="审核结论"><el-segmented v-model="decision" :options="decisionOptions" /></el-form-item><el-form-item :required="decision === 'REJECTED'" :label="decision === 'REJECTED' ? '驳回原因' : '审核意见'"><el-input v-model="opinion" type="textarea" :rows="4" maxlength="1000" show-word-limit :placeholder="decision === 'REJECTED' ? '请明确说明需要修改或补充的内容' : '可选填写本次审核说明'" /></el-form-item></el-form></template><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button v-if="decision" :type="decision === 'REJECTED' ? 'danger' : 'primary'" :loading="reviewing" @click="submitAudit">确认{{ actionLabels[decision] }}</el-button></template></el-dialog>
  </section>
</template>
